from pathlib import Path
import shutil
import sys

ROOT = Path(__file__).resolve().parent
DATA_DIR = ROOT / 'data'

def write_file(relative_path: str, content: str):
    path = ROOT / relative_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.strip() + '\n', encoding='utf-8')
    print(f'updated: {relative_path}')

def backup_csv_files():
    backup_dir = DATA_DIR / 'csv_backup_before_sqlite'
    backup_dir.mkdir(parents=True, exist_ok=True)
    csv_files = ['sample_resources.csv','sample_tasks.csv','task_history.csv','past_cases.csv','assignment_logs.csv','ml_training_candidates.csv']
    copied = 0
    for filename in csv_files:
        src = DATA_DIR / filename
        if src.exists():
            shutil.copy2(src, backup_dir / filename)
            copied += 1
    print(f'backed up {copied} CSV file(s) to: data/csv_backup_before_sqlite')

backup_csv_files()

FILES = {
    'backend/app/sqlite_database.py': '\nimport csv\nimport sqlite3\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional\n\n\nDATA_DIR = Path(__file__).resolve().parents[2] / "data"\nDB_PATH = DATA_DIR / "app.db"\n\nRESOURCE_FIELDS = [\n    "resource_id", "name", "skills", "experience_level", "status",\n    "current_tasks", "max_tasks", "shift_start", "shift_end",\n    "success_rate", "avg_resolution_minutes", "handled_categories",\n]\n\nTASK_FIELDS = [\n    "task_id", "title", "description", "priority", "category",\n    "required_skills", "sla_minutes",\n]\n\nTASK_HISTORY_FIELDS = [\n    "history_id", "task_id", "resource_id", "category",\n    "completed_minutes", "success", "customer_rating", "escalated",\n]\n\nPAST_CASE_FIELDS = [\n    "case_id", "title", "description", "category", "skills",\n    "resource_name", "completed_minutes", "success", "customer_rating",\n    "escalated", "resolution_notes",\n]\n\nASSIGNMENT_LOG_FIELDS = [\n    "log_id", "timestamp", "mode", "task_title", "task_category",\n    "task_priority", "required_skills", "assigned", "assigned_resource",\n    "score", "base_score", "rag_bonus", "explanation",\n]\n\nML_TRAINING_FIELDS = [\n    "row_id", "timestamp", "mode", "task_title", "task_category",\n    "task_priority", "candidate_resource_id", "candidate_resource_name",\n    "priority_value", "eligible", "base_score", "rag_bonus",\n    "deterministic_score", "skill_match", "availability", "workload",\n    "category_match", "past_performance", "experience", "speed",\n    "rejection_count", "label_selected",\n]\n\n\ndef _connect() -> sqlite3.Connection:\n    DATA_DIR.mkdir(parents=True, exist_ok=True)\n    conn = sqlite3.connect(DB_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\ndef _split_list(value: Any) -> List[str]:\n    if value is None:\n        return []\n    return [item.strip().lower() for item in str(value).replace(",", ";").split(";") if item.strip()]\n\n\ndef _join_list(value: Any) -> str:\n    if isinstance(value, list):\n        return ";".join(str(item).strip().lower() for item in value if str(item).strip())\n    return str(value or "")\n\n\ndef _read_csv(filename: str) -> List[Dict[str, Any]]:\n    path = DATA_DIR / filename\n    if not path.exists():\n        return []\n\n    with path.open("r", encoding="utf-8-sig", newline="") as file:\n        return list(csv.DictReader(file))\n\n\ndef _table_count(conn: sqlite3.Connection, table: str) -> int:\n    row = conn.execute(f"SELECT COUNT(*) AS count FROM {table}").fetchone()\n    return int(row["count"])\n\n\ndef _insert_many(conn: sqlite3.Connection, table: str, fields: List[str], rows: List[Dict[str, Any]]) -> None:\n    if not rows:\n        return\n\n    placeholders = ", ".join(["?"] * len(fields))\n    columns = ", ".join(fields)\n    sql = f"INSERT OR REPLACE INTO {table} ({columns}) VALUES ({placeholders})"\n    values = [[row.get(field, "") for field in fields] for row in rows]\n    conn.executemany(sql, values)\n\n\ndef init_db() -> None:\n    with _connect() as conn:\n        conn.execute("""\n            CREATE TABLE IF NOT EXISTS resources (\n                resource_id TEXT PRIMARY KEY,\n                name TEXT NOT NULL,\n                skills TEXT,\n                experience_level INTEGER,\n                status TEXT,\n                current_tasks INTEGER,\n                max_tasks INTEGER,\n                shift_start TEXT,\n                shift_end TEXT,\n                success_rate REAL,\n                avg_resolution_minutes REAL,\n                handled_categories TEXT\n            )\n        """)\n\n        conn.execute("""\n            CREATE TABLE IF NOT EXISTS tasks (\n                task_id TEXT PRIMARY KEY,\n                title TEXT NOT NULL,\n                description TEXT,\n                priority TEXT,\n                category TEXT,\n                required_skills TEXT,\n                sla_minutes INTEGER\n            )\n        """)\n\n        conn.execute("""\n            CREATE TABLE IF NOT EXISTS task_history (\n                history_id TEXT PRIMARY KEY,\n                task_id TEXT,\n                resource_id TEXT,\n                category TEXT,\n                completed_minutes REAL,\n                success TEXT,\n                customer_rating REAL,\n                escalated TEXT\n            )\n        """)\n\n        conn.execute("""\n            CREATE TABLE IF NOT EXISTS past_cases (\n                case_id TEXT PRIMARY KEY,\n                title TEXT,\n                description TEXT,\n                category TEXT,\n                skills TEXT,\n                resource_name TEXT,\n                completed_minutes REAL,\n                success TEXT,\n                customer_rating REAL,\n                escalated TEXT,\n                resolution_notes TEXT\n            )\n        """)\n\n        conn.execute("""\n            CREATE TABLE IF NOT EXISTS assignment_logs (\n                log_id TEXT PRIMARY KEY,\n                timestamp TEXT,\n                mode TEXT,\n                task_title TEXT,\n                task_category TEXT,\n                task_priority TEXT,\n                required_skills TEXT,\n                assigned TEXT,\n                assigned_resource TEXT,\n                score TEXT,\n                base_score TEXT,\n                rag_bonus TEXT,\n                explanation TEXT\n            )\n        """)\n\n        conn.execute("""\n            CREATE TABLE IF NOT EXISTS ml_training_candidates (\n                row_id TEXT PRIMARY KEY,\n                timestamp TEXT,\n                mode TEXT,\n                task_title TEXT,\n                task_category TEXT,\n                task_priority TEXT,\n                candidate_resource_id TEXT,\n                candidate_resource_name TEXT,\n                priority_value REAL,\n                eligible REAL,\n                base_score REAL,\n                rag_bonus REAL,\n                deterministic_score REAL,\n                skill_match REAL,\n                availability REAL,\n                workload REAL,\n                category_match REAL,\n                past_performance REAL,\n                experience REAL,\n                speed REAL,\n                rejection_count REAL,\n                label_selected INTEGER\n            )\n        """)\n\n        if _table_count(conn, "resources") == 0:\n            _insert_many(conn, "resources", RESOURCE_FIELDS, _read_csv("sample_resources.csv"))\n        if _table_count(conn, "tasks") == 0:\n            _insert_many(conn, "tasks", TASK_FIELDS, _read_csv("sample_tasks.csv"))\n        if _table_count(conn, "task_history") == 0:\n            _insert_many(conn, "task_history", TASK_HISTORY_FIELDS, _read_csv("task_history.csv"))\n        if _table_count(conn, "past_cases") == 0:\n            _insert_many(conn, "past_cases", PAST_CASE_FIELDS, _read_csv("past_cases.csv"))\n        if _table_count(conn, "assignment_logs") == 0:\n            _insert_many(conn, "assignment_logs", ASSIGNMENT_LOG_FIELDS, _read_csv("assignment_logs.csv"))\n        if _table_count(conn, "ml_training_candidates") == 0:\n            _insert_many(conn, "ml_training_candidates", ML_TRAINING_FIELDS, _read_csv("ml_training_candidates.csv"))\n\n        conn.commit()\n\n\ndef _fetch_all(table: str, order_by: Optional[str] = None, limit: Optional[int] = None) -> List[Dict[str, Any]]:\n    init_db()\n    sql = f"SELECT * FROM {table}"\n    if order_by:\n        sql += f" ORDER BY {order_by}"\n    if limit:\n        sql += f" LIMIT {int(limit)}"\n\n    with _connect() as conn:\n        rows = conn.execute(sql).fetchall()\n\n    return [dict(row) for row in rows]\n\n\ndef load_resources() -> List[Dict[str, Any]]:\n    rows = _fetch_all("resources", order_by="resource_id ASC")\n\n    for row in rows:\n        row["skills"] = _split_list(row.get("skills"))\n        row["handled_categories"] = _split_list(row.get("handled_categories"))\n        row["experience_level"] = int(float(row.get("experience_level") or 1))\n        row["current_tasks"] = int(float(row.get("current_tasks") or 0))\n        row["max_tasks"] = int(float(row.get("max_tasks") or 3))\n        row["success_rate"] = float(row.get("success_rate") or 0.5)\n        row["avg_resolution_minutes"] = float(row.get("avg_resolution_minutes") or 120)\n        row["status"] = str(row.get("status") or "offline").lower()\n\n    return rows\n\n\ndef save_resources(resources: List[Dict[str, Any]]) -> None:\n    init_db()\n\n    rows = []\n    for resource in resources:\n        row = dict(resource)\n        row["skills"] = _join_list(row.get("skills"))\n        row["handled_categories"] = _join_list(row.get("handled_categories"))\n        rows.append({field: row.get(field, "") for field in RESOURCE_FIELDS})\n\n    with _connect() as conn:\n        conn.execute("DELETE FROM resources")\n        _insert_many(conn, "resources", RESOURCE_FIELDS, rows)\n        conn.commit()\n\n\ndef load_tasks() -> List[Dict[str, Any]]:\n    rows = _fetch_all("tasks", order_by="task_id ASC")\n\n    for row in rows:\n        row["required_skills"] = _split_list(row.get("required_skills"))\n        row["sla_minutes"] = int(float(row.get("sla_minutes") or 120))\n\n    return rows\n\n\ndef load_history() -> List[Dict[str, Any]]:\n    return _fetch_all("task_history", order_by="history_id ASC")\n\n\ndef load_past_cases() -> List[Dict[str, Any]]:\n    return _fetch_all("past_cases", order_by="case_id ASC")\n\n\ndef load_assignment_logs(limit: int = 50) -> List[Dict[str, Any]]:\n    return _fetch_all("assignment_logs", order_by="timestamp DESC", limit=limit)\n\n\ndef append_assignment_log(result: Dict[str, Any]) -> Dict[str, Any]:\n    init_db()\n\n    task = result.get("task", {}) or {}\n    assigned_resource = result.get("assigned_resource") or {}\n\n    log_row = {\n        "log_id": datetime.now().strftime("%Y%m%d%H%M%S%f"),\n        "timestamp": datetime.now().isoformat(timespec="seconds"),\n        "mode": result.get("mode") or "normal_scoring",\n        "task_title": task.get("title", ""),\n        "task_category": task.get("category", ""),\n        "task_priority": task.get("priority", ""),\n        "required_skills": ", ".join(task.get("required_skills", []) or []),\n        "assigned": str(result.get("assigned", False)),\n        "assigned_resource": assigned_resource.get("name", "") if assigned_resource else "",\n        "score": assigned_resource.get("score", "") if assigned_resource else "",\n        "base_score": assigned_resource.get("base_score", "") if assigned_resource else "",\n        "rag_bonus": assigned_resource.get("rag_bonus", "") if assigned_resource else "",\n        "explanation": result.get("explanation", ""),\n    }\n\n    with _connect() as conn:\n        _insert_many(conn, "assignment_logs", ASSIGNMENT_LOG_FIELDS, [log_row])\n        conn.commit()\n\n    return log_row\n\n\ndef load_ml_training_rows() -> List[Dict[str, Any]]:\n    return _fetch_all("ml_training_candidates", order_by="timestamp ASC")\n\n\ndef append_ml_training_rows(rows: List[Dict[str, Any]]) -> int:\n    init_db()\n    clean_rows = [{field: row.get(field, "") for field in ML_TRAINING_FIELDS} for row in rows]\n\n    with _connect() as conn:\n        _insert_many(conn, "ml_training_candidates", ML_TRAINING_FIELDS, clean_rows)\n        conn.commit()\n\n    return len(clean_rows)\n\n\ndef clear_ml_training_rows() -> None:\n    init_db()\n    with _connect() as conn:\n        conn.execute("DELETE FROM ml_training_candidates")\n        conn.commit()\n\n\ndef get_db_status() -> Dict[str, Any]:\n    init_db()\n\n    tables = [\n        "resources", "tasks", "task_history", "past_cases",\n        "assignment_logs", "ml_training_candidates",\n    ]\n\n    with _connect() as conn:\n        counts = {table: _table_count(conn, table) for table in tables}\n\n    return {\n        "database_path": str(DB_PATH),\n        "database_exists": DB_PATH.exists(),\n        "tables": counts,\n        "storage": "sqlite",\n    }\n\n\ninit_db()\n',
    'backend/app/database.py': '\nfrom .sqlite_database import (\n    append_assignment_log,\n    append_ml_training_rows,\n    clear_ml_training_rows,\n    get_db_status,\n    load_assignment_logs,\n    load_history,\n    load_ml_training_rows,\n    load_past_cases,\n    load_resources,\n    load_tasks,\n    save_resources,\n)\n',
    'backend/app/rag_engine.py': '\nimport math\nfrom pathlib import Path\nfrom typing import Dict, List\n\nfrom .database import load_past_cases\n\n\nDATA_DIR = Path(__file__).resolve().parents[2] / "data"\nPOLICY_PATH = DATA_DIR / "knowledge_base" / "support_policy.txt"\n\n\ndef _tokenize(text: str) -> set:\n    clean = ""\n    for char in str(text).lower():\n        clean += char if char.isalnum() else " "\n    return {token for token in clean.split() if len(token) > 2}\n\n\ndef _similarity(a: str, b: str) -> float:\n    a_tokens = _tokenize(a)\n    b_tokens = _tokenize(b)\n\n    if not a_tokens or not b_tokens:\n        return 0.0\n\n    overlap = len(a_tokens.intersection(b_tokens))\n    denominator = math.sqrt(len(a_tokens) * len(b_tokens))\n    return round(overlap / denominator, 4)\n\n\ndef _read_policy() -> str:\n    if not POLICY_PATH.exists():\n        return ""\n\n    return POLICY_PATH.read_text(encoding="utf-8")\n\n\ndef retrieve_similar_cases(task: Dict, top_k: int = 5) -> List[Dict]:\n    cases = load_past_cases()\n    query = " ".join([\n        str(task.get("title", "")),\n        str(task.get("description", "")),\n        str(task.get("category", "")),\n        " ".join(task.get("required_skills", []) or []),\n    ])\n\n    scored = []\n    for case in cases:\n        case_text = " ".join([\n            case.get("title", ""),\n            case.get("description", ""),\n            case.get("category", ""),\n            case.get("skills", ""),\n            case.get("resolution_notes", ""),\n        ])\n\n        score = _similarity(query, case_text)\n\n        if str(task.get("category", "")).lower() == str(case.get("category", "")).lower():\n            score += 0.15\n\n        scored.append({\n            **case,\n            "similarity_score": round(min(score, 1.0), 4),\n        })\n\n    scored.sort(key=lambda item: item["similarity_score"], reverse=True)\n    return [item for item in scored[:top_k] if item["similarity_score"] > 0]\n\n\ndef retrieve_policy_context(task: Dict) -> List[str]:\n    policy_text = _read_policy()\n    if not policy_text:\n        return []\n\n    chunks = [chunk.strip() for chunk in policy_text.split("\\n\\n") if chunk.strip()]\n\n    query = " ".join([\n        str(task.get("title", "")),\n        str(task.get("description", "")),\n        str(task.get("category", "")),\n        str(task.get("priority", "")),\n    ])\n\n    scored_chunks = [\n        {"text": chunk, "score": _similarity(query, chunk)}\n        for chunk in chunks\n    ]\n\n    scored_chunks.sort(key=lambda item: item["score"], reverse=True)\n    return [item["text"] for item in scored_chunks[:3] if item["score"] > 0]\n\n\ndef build_rag_context(task: Dict) -> Dict:\n    similar_cases = retrieve_similar_cases(task)\n    policy_context = retrieve_policy_context(task)\n    resource_case_stats = {}\n\n    for case in similar_cases:\n        resource_name = case.get("resource_name", "")\n        if not resource_name:\n            continue\n\n        stats = resource_case_stats.setdefault(resource_name, {\n            "similar_cases": 0,\n            "successful_cases": 0,\n            "escalations": 0,\n            "avg_resolution_minutes": [],\n            "similarity_total": 0.0,\n        })\n\n        stats["similar_cases"] += 1\n        stats["similarity_total"] += float(case.get("similarity_score") or 0)\n\n        if str(case.get("success", "")).lower() == "true":\n            stats["successful_cases"] += 1\n\n        if str(case.get("escalated", "")).lower() == "true":\n            stats["escalations"] += 1\n\n        try:\n            stats["avg_resolution_minutes"].append(float(case.get("completed_minutes") or 0))\n        except ValueError:\n            pass\n\n    for stats in resource_case_stats.values():\n        values = stats["avg_resolution_minutes"]\n        stats["avg_resolution_minutes"] = round(sum(values) / len(values), 2) if values else None\n        stats["avg_similarity"] = round(stats["similarity_total"] / max(stats["similar_cases"], 1), 4)\n\n    return {\n        "similar_cases": similar_cases,\n        "policy_context": policy_context,\n        "resource_case_stats": resource_case_stats,\n    }\n',
    'backend/app/ml_ranking_model.py': '\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Dict, Optional\n\nimport joblib\nimport pandas as pd\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.metrics import accuracy_score\n\nfrom .database import append_ml_training_rows, load_ml_training_rows\n\n\nDATA_DIR = Path(__file__).resolve().parents[2] / "data"\nMODEL_DIR = DATA_DIR / "models"\nMODEL_PATH = MODEL_DIR / "assignment_ranker.joblib"\nMETADATA_PATH = MODEL_DIR / "assignment_ranker_metadata.json"\n\nFEATURE_COLUMNS = [\n    "priority_value", "eligible", "base_score", "rag_bonus",\n    "deterministic_score", "skill_match", "availability", "workload",\n    "category_match", "past_performance", "experience", "speed",\n    "rejection_count",\n]\n\nPRIORITY_VALUE = {\n    "urgent": 4,\n    "high": 3,\n    "medium": 2,\n    "low": 1,\n}\n\n\ndef _priority_value(priority: str) -> int:\n    return PRIORITY_VALUE.get(str(priority).lower(), 2)\n\n\ndef _safe_float(value, default=0.0) -> float:\n    try:\n        return float(value)\n    except (TypeError, ValueError):\n        return default\n\n\ndef _candidate_to_features(task: Dict, candidate: Dict) -> Dict:\n    breakdown = candidate.get("breakdown", {}) or {}\n\n    return {\n        "priority_value": _priority_value(task.get("priority")),\n        "eligible": 1 if candidate.get("eligible") else 0,\n        "base_score": _safe_float(candidate.get("base_score", candidate.get("final_score"))),\n        "rag_bonus": _safe_float(candidate.get("rag_bonus")),\n        "deterministic_score": _safe_float(candidate.get("base_rag_score", candidate.get("final_score"))),\n        "skill_match": _safe_float(breakdown.get("skill_match")),\n        "availability": _safe_float(breakdown.get("availability")),\n        "workload": _safe_float(breakdown.get("workload")),\n        "category_match": _safe_float(breakdown.get("category_match")),\n        "past_performance": _safe_float(breakdown.get("past_performance")),\n        "experience": _safe_float(breakdown.get("experience")),\n        "speed": _safe_float(breakdown.get("speed")),\n        "rejection_count": len(candidate.get("rejection_reasons", []) or []),\n    }\n\n\ndef append_candidate_training_rows(result: Dict) -> int:\n    if not result.get("assigned") or not result.get("assigned_resource"):\n        return 0\n\n    candidates = result.get("candidates", []) or []\n    if not candidates:\n        return 0\n\n    task = result.get("task", {}) or {}\n    assigned_resource_id = result.get("assigned_resource", {}).get("resource_id")\n    assigned_resource_name = result.get("assigned_resource", {}).get("name")\n    rows = []\n\n    for candidate in candidates:\n        features = _candidate_to_features(task, candidate)\n        label = int(\n            candidate.get("resource_id") == assigned_resource_id\n            or candidate.get("resource_name") == assigned_resource_name\n        )\n\n        rows.append({\n            "row_id": datetime.now().strftime("%Y%m%d%H%M%S%f") + str(len(rows)),\n            "timestamp": datetime.now().isoformat(timespec="seconds"),\n            "mode": result.get("mode", "normal_scoring"),\n            "task_title": task.get("title", ""),\n            "task_category": task.get("category", ""),\n            "task_priority": task.get("priority", ""),\n            "candidate_resource_id": candidate.get("resource_id", ""),\n            "candidate_resource_name": candidate.get("resource_name", ""),\n            **features,\n            "label_selected": label,\n        })\n\n    return append_ml_training_rows(rows)\n\n\ndef get_ml_status() -> Dict:\n    rows = load_ml_training_rows()\n    training_rows = len(rows)\n    positive_rows = sum(1 for row in rows if int(float(row.get("label_selected") or 0)) == 1)\n    negative_rows = training_rows - positive_rows\n\n    metadata = {}\n    if METADATA_PATH.exists():\n        metadata = json.loads(METADATA_PATH.read_text(encoding="utf-8"))\n\n    return {\n        "model_exists": MODEL_PATH.exists(),\n        "training_file_exists": training_rows > 0,\n        "training_rows": training_rows,\n        "positive_rows": positive_rows,\n        "negative_rows": negative_rows,\n        "model_path": str(MODEL_PATH),\n        "metadata": metadata,\n        "storage": "sqlite",\n    }\n\n\ndef train_ml_model() -> Dict:\n    rows = load_ml_training_rows()\n\n    if not rows:\n        return {\n            "trained": False,\n            "message": "No candidate training data found yet. Run a few assignments first.",\n            "status": get_ml_status(),\n        }\n\n    df = pd.DataFrame(rows)\n\n    if len(df) < 4:\n        return {\n            "trained": False,\n            "message": "Not enough candidate rows yet. Run a few more assignments.",\n            "status": get_ml_status(),\n        }\n\n    df["label_selected"] = pd.to_numeric(df["label_selected"], errors="coerce").fillna(0).astype(int)\n\n    if df["label_selected"].nunique() < 2:\n        return {\n            "trained": False,\n            "message": "Training data needs both selected and non-selected candidates.",\n            "status": get_ml_status(),\n        }\n\n    for column in FEATURE_COLUMNS:\n        if column not in df.columns:\n            df[column] = 0\n        df[column] = pd.to_numeric(df[column], errors="coerce").fillna(0)\n\n    X = df[FEATURE_COLUMNS].fillna(0)\n    y = df["label_selected"].astype(int)\n\n    model = RandomForestClassifier(\n        n_estimators=120,\n        max_depth=8,\n        random_state=42,\n        class_weight="balanced",\n    )\n    model.fit(X, y)\n\n    predictions = model.predict(X)\n    train_accuracy = float(accuracy_score(y, predictions))\n\n    MODEL_DIR.mkdir(parents=True, exist_ok=True)\n    joblib.dump(model, MODEL_PATH)\n\n    importances = sorted(\n        zip(FEATURE_COLUMNS, model.feature_importances_),\n        key=lambda item: item[1],\n        reverse=True,\n    )\n\n    metadata = {\n        "trained_at": datetime.now().isoformat(timespec="seconds"),\n        "training_rows": int(len(df)),\n        "positive_rows": int((y == 1).sum()),\n        "negative_rows": int((y == 0).sum()),\n        "train_accuracy": round(train_accuracy, 4),\n        "storage": "sqlite",\n        "top_features": [\n            {"feature": feature, "importance": round(float(value), 4)}\n            for feature, value in importances[:8]\n        ],\n    }\n\n    METADATA_PATH.write_text(json.dumps(metadata, indent=2), encoding="utf-8")\n\n    return {\n        "trained": True,\n        "message": "ML ranking model trained successfully.",\n        "metadata": metadata,\n        "status": get_ml_status(),\n    }\n\n\ndef _load_model():\n    if not MODEL_PATH.exists():\n        return None\n    return joblib.load(MODEL_PATH)\n\n\ndef _predict_candidate_probability(model, task: Dict, candidate: Dict) -> float:\n    features = _candidate_to_features(task, candidate)\n    X = pd.DataFrame([{column: features.get(column, 0) for column in FEATURE_COLUMNS}])\n\n    if hasattr(model, "predict_proba"):\n        return float(model.predict_proba(X)[0][1])\n\n    return float(model.predict(X)[0])\n\n\ndef _append_ml_workflow_step(result: Dict, model_available: bool, winner: Optional[Dict]) -> None:\n    trace = result.get("workflow_trace") or []\n\n    trace.append({\n        "name": "ML Ranker",\n        "status": "completed" if model_available else "fallback",\n        "detail": (\n            "Trained ML model re-ranked eligible candidates using candidate-level training history from SQLite."\n            if model_available\n            else "No trained ML model found, so the system used Agentic RAG scoring as fallback."\n        ),\n        "data": {\n            "model_available": model_available,\n            "selected_by_ml": winner.get("resource_name") if winner else None,\n            "ml_score": winner.get("ml_score") if winner else None,\n        },\n    })\n\n    result["workflow_trace"] = trace\n\n\ndef assign_task_ml(task: Dict, now_hhmm: Optional[str] = None) -> Dict:\n    from .agentic_assignment_engine import assign_task_agentic\n\n    result = assign_task_agentic(task, now_hhmm=now_hhmm)\n    model = _load_model()\n\n    if model is None or not result.get("assigned"):\n        result["mode"] = "ml_ranker_fallback"\n        result["explanation"] = (\n            result.get("explanation", "")\n            + " ML ranker fallback was used because no trained model is available yet."\n        ).strip()\n        _append_ml_workflow_step(result, False, None)\n        return result\n\n    task_data = result.get("task", {}) or {}\n    candidates = result.get("candidates", []) or []\n\n    for candidate in candidates:\n        candidate["base_rag_score"] = candidate.get("final_score", 0)\n\n        if candidate.get("eligible"):\n            probability = _predict_candidate_probability(model, task_data, candidate)\n            candidate["ml_probability"] = round(probability, 4)\n            candidate["ml_score"] = round((probability * 100 * 0.65) + (candidate["base_rag_score"] * 0.35), 2)\n            candidate["final_score"] = candidate["ml_score"]\n            candidate["positive_reasons"] = candidate.get("positive_reasons", []) + [\n                f"ML ranker probability {round(probability * 100, 2)}%"\n            ]\n        else:\n            candidate["ml_probability"] = 0.0\n            candidate["ml_score"] = 0.0\n\n    candidates.sort(key=lambda item: item.get("final_score", 0), reverse=True)\n    valid_candidates = [candidate for candidate in candidates if candidate.get("eligible")]\n\n    if not valid_candidates:\n        result["mode"] = "ml_ranker"\n        result["assigned"] = False\n        result["assigned_resource"] = None\n        _append_ml_workflow_step(result, True, None)\n        return result\n\n    winner = valid_candidates[0]\n\n    result["mode"] = "ml_ranker"\n    result["candidates"] = candidates\n    result["assigned"] = True\n    result["assigned_resource"] = {\n        "resource_id": winner["resource_id"],\n        "name": winner["resource_name"],\n        "score": winner["final_score"],\n        "base_score": winner.get("base_score"),\n        "rag_bonus": winner.get("rag_bonus"),\n        "ml_probability": winner.get("ml_probability"),\n        "ml_score": winner.get("ml_score"),\n    }\n\n    result["explanation"] = (\n        f"ML Ranker assigned this task to {winner.get(\'resource_name\')} after using "\n        f"Agentic RAG evidence plus the trained candidate-ranking model. "\n        f"The selected candidate received ML probability "\n        f"{round(winner.get(\'ml_probability\', 0) * 100, 2)}% and blended score "\n        f"{winner.get(\'ml_score\')}. "\n        f"Original explanation: {result.get(\'explanation\', \'\')}"\n    )\n\n    _append_ml_workflow_step(result, True, winner)\n    return result\n',
    'backend/app/main.py': '\nfrom typing import Optional\n\nfrom fastapi import FastAPI, HTTPException, Query\nfrom fastapi.middleware.cors import CORSMiddleware\n\nfrom .agentic_assignment_engine import assign_task_agentic\nfrom .analytics_engine import build_analytics_summary\nfrom .assignment_engine import assign_single_task, assign_tasks\nfrom .database import (\n    append_assignment_log,\n    get_db_status,\n    load_assignment_logs,\n    load_history,\n    load_resources,\n    load_tasks,\n    save_resources,\n)\nfrom .ml_ranking_model import (\n    append_candidate_training_rows,\n    assign_task_ml,\n    get_ml_status,\n    train_ml_model,\n)\nfrom .schemas import AssignmentRequest, ResourceIn, TaskIn\n\n\napp = FastAPI(\n    title="AI Task Allocation System",\n    description="Smart workforce task allocation using deterministic scoring, Agentic RAG, workflow traces, assignment history, trainable ML ranking, analytics, and SQLite persistence.",\n    version="1.6.0",\n)\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=["*"],\n    allow_credentials=True,\n    allow_methods=["*"],\n    allow_headers=["*"],\n)\n\n\ndef _next_resource_id(resources):\n    used_numbers = []\n    for resource in resources:\n        rid = str(resource.get("resource_id", "")).upper().replace("R", "")\n        if rid.isdigit():\n            used_numbers.append(int(rid))\n    return f"R{max(used_numbers, default=0) + 1}"\n\n\ndef _log_result(result):\n    append_assignment_log(result)\n    append_candidate_training_rows(result)\n\n\n@app.get("/")\ndef health_check():\n    return {\n        "status": "ok",\n        "app": "AI Task Allocation System",\n        "message": "Backend is running. Open /docs for API testing.",\n    }\n\n\n@app.get("/db/status")\ndef db_status():\n    return get_db_status()\n\n\n@app.get("/analytics/summary")\ndef analytics_summary(limit: int = Query(default=500, ge=1, le=2000)):\n    return build_analytics_summary(limit=limit)\n\n\n@app.get("/resources")\ndef get_resources():\n    return load_resources()\n\n\n@app.post("/resources")\ndef create_resource(resource: ResourceIn):\n    resources = load_resources()\n    data = resource.model_dump()\n\n    if not data["resource_id"]:\n        data["resource_id"] = _next_resource_id(resources)\n\n    if any(item["resource_id"] == data["resource_id"] for item in resources):\n        raise HTTPException(status_code=409, detail="Resource ID already exists.")\n\n    data["skills"] = [skill.strip().lower() for skill in data["skills"] if skill.strip()]\n    data["handled_categories"] = [\n        category.strip().lower()\n        for category in data["handled_categories"]\n        if category.strip()\n    ]\n    data["status"] = data["status"].lower()\n\n    resources.append(data)\n    save_resources(resources)\n\n    return {\n        "message": "Resource created successfully.",\n        "resource": data,\n    }\n\n\n@app.put("/resources/{resource_id}")\ndef update_resource(resource_id: str, resource: ResourceIn):\n    resources = load_resources()\n    data = resource.model_dump()\n    data["resource_id"] = resource_id\n    data["skills"] = [skill.strip().lower() for skill in data["skills"] if skill.strip()]\n    data["handled_categories"] = [\n        category.strip().lower()\n        for category in data["handled_categories"]\n        if category.strip()\n    ]\n    data["status"] = data["status"].lower()\n\n    for index, existing in enumerate(resources):\n        if existing["resource_id"] == resource_id:\n            resources[index] = data\n            save_resources(resources)\n            return {\n                "message": "Resource updated successfully.",\n                "resource": data,\n            }\n\n    raise HTTPException(status_code=404, detail="Resource not found.")\n\n\n@app.delete("/resources/{resource_id}")\ndef delete_resource(resource_id: str):\n    resources = load_resources()\n    remaining = [resource for resource in resources if resource["resource_id"] != resource_id]\n\n    if len(remaining) == len(resources):\n        raise HTTPException(status_code=404, detail="Resource not found.")\n\n    save_resources(remaining)\n\n    return {\n        "message": "Resource deleted successfully.",\n        "resource_id": resource_id,\n    }\n\n\n@app.get("/tasks")\ndef get_tasks():\n    return load_tasks()\n\n\n@app.get("/history")\ndef get_history():\n    return load_history()\n\n\n@app.get("/assignment-logs")\ndef get_assignment_logs(limit: int = Query(default=50, ge=1, le=500)):\n    return load_assignment_logs(limit=limit)\n\n\n@app.get("/ml/status")\ndef ml_status():\n    return get_ml_status()\n\n\n@app.post("/ml/train")\ndef ml_train():\n    return train_ml_model()\n\n\n@app.post("/assign")\ndef assign_task(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_single_task(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/agentic")\ndef assign_task_with_agentic_rag(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_task_agentic(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/ml")\ndef assign_task_with_ml_ranker(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_task_ml(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/batch")\ndef assign_batch(payload: AssignmentRequest):\n    result = assign_tasks(\n        [task.model_dump() for task in payload.tasks],\n        now_hhmm=payload.now_hhmm,\n    )\n\n    for item in result.get("assignments", []):\n        _log_result(item)\n\n    return result\n\n\n@app.post("/assign/sample")\ndef assign_sample(now_hhmm: Optional[str] = Query(default="10:30")):\n    result = assign_tasks(load_tasks(), now_hhmm=now_hhmm)\n\n    for item in result.get("assignments", []):\n        _log_result(item)\n\n    return result\n',
}

